    private val TYPES = mapOf('c' to ReactionType.COMBINATION, 'd' to ReactionType.DECOMPOSITION, 's' to ReactionType.DISPLACEMENT, 'x' to ReactionType.DOUBLE_DISPLACEMENT, 'r' to ReactionType.REDOX)

    /** What is drawn for each condition key; anything that is not light, heat or a flame is a tag. */
    private fun visuals(key: String, label: L10n?): List<ConditionVisual> {
        label ?: return emptyList()
        val heat = L10n("加热", "heat")
        val catalyst = L10n("催化剂", "catalyst")
        return when (key) {
            "ign" -> listOf(ConditionVisual(ConditionKind.IGNITE, label))
            "light" -> listOf(ConditionVisual(ConditionKind.LIGHT, label))
            "heat", "high", "hot" -> listOf(ConditionVisual(ConditionKind.HEAT, label))
            "mno2" -> listOf(ConditionVisual(ConditionKind.CATALYST, L10n("MnO₂ 催化剂", "MnO₂ catalyst")))
            "mno2h" -> listOf(ConditionVisual(ConditionKind.HEAT, heat), ConditionVisual(ConditionKind.CATALYST, L10n("MnO₂ 催化剂", "MnO₂ catalyst")))
            "cath" -> listOf(ConditionVisual(ConditionKind.HEAT, heat), ConditionVisual(ConditionKind.CATALYST, catalyst))
            "nh3" -> listOf(ConditionVisual(ConditionKind.HEAT, L10n("高温高压", "high T and p")), ConditionVisual(ConditionKind.CATALYST, catalyst))
            "conc" -> listOf(ConditionVisual(ConditionKind.HEAT, heat), ConditionVisual(ConditionKind.CATALYST, L10n("浓硫酸", "conc. H₂SO₄")))
            else -> listOf(ConditionVisual(ConditionKind.NOTE, label))
        }
    }

    val ALL: List<Reaction> by lazy {
        ROWS.map { row ->
            val src = SOURCES.getValue(row.source)
            val condition = CONDITIONS[row.condition]
            AutoReaction.build(
                AutoReaction.Spec(
                    id = row.id,
                    equation = row.equation,
                    condition = condition,
                    visuals = visuals(row.condition, condition),
                    types = row.types.map { TYPES.getValue(it) },
                    stages = setOfNotNull(src.stage),
                    source = src.text,
                    phenomenon = L10n(row.zh, row.en),
                )
            )
        }
    }
}
